    "msglog": {
      titel: "Meldungen",
      zweck: "Zeigt Meldungen aus zwei Quellen: dem IP-Symcon-Logfile (DEBUG ausgefiltert) ODER den Servicemeldungen einer Homematic-CCU (per XML-RPC + ReGaHss, es genügt die CCU-IP). Kategorien per Pille filterbar; Ansicht als Liste oder als Kompakt-Zähler: eine große Gesamtzahl der markierten Kategorien.",
      funktionen: [
        {name: "Typ (Quelle)", beschreibung: "Symcon-Log oder Homematic-CCU. Bei Homematic wird die CCU-IP eingetragen; gelesen werden BidCos- und HmIP-Servicemeldungen zusammen, Gerätenamen werden aufgelöst."},
        {name: "Quelle live umschalten (kein Feld)", beschreibung: "Ist eine CCU-IP hinterlegt, erscheint in der Listen-Ansicht im Kopf ein kleiner Umschalter Symcon/HM. Ein Tipp wechselt die Quelle im Betrieb (je Gerät gespeichert). Im Kompaktmodus ausgeblendet."},
        {name: "Bestätigen erlauben (nur Homematic)", beschreibung: "Blendet je Meldung einen Haken ein, der die Servicemeldung auf der CCU quittiert (ReGaHss AlReceipt). Danach wird die Liste neu geladen."},
        {name: "Bestätigen (nur Symcon) · Bestätigt-bis-Variable", beschreibung: "Das Symcon-Log ist append-only, einzelne Zeilen lassen sich nicht löschen. Deshalb hält eine gebundene String-Variable den Bestätigt-Status als JSON {cutoff, keys}: cutoff = Stichzeitpunkt (Unix-Zeit), keys = einzeln ausgeblendete Meldungen. Der Knopf „Bestätigen“ setzt cutoff auf jetzt (blendet alles Bisherige aus); das ✕ je Zeile blendet eine einzelne Meldung aus (Schlüssel aus Zeit+Text). Die Variable liegt auf dem Server → geräteübergreifend. Reine Integer-Variablen werden weiter als „nur cutoff“ akzeptiert (abwärtskompatibel). Ohne gebundene Variable erscheinen keine Bestätigen-Bedienelemente. In der Kompaktansicht gibt es ein kleines Haken-Symbol oben rechts (bestätigt alles); ein Tipp auf die Zahl bleibt frei für Navigation/Popup."},
        {name: "Farbgrenzen (Anzahl) - nur Kompakt", beschreibung: "Zwei Schwellen teilen die Anzahl in drei Bereiche: 0 bis gruen-Grenze, bis gelb-Grenze, darueber (Beispiel 10/20: 0-10, 11-20, ab 21). Je Bereich lassen sich Schriftfarbe UND Kachelfarbe frei aus den Skin-Farben waehlen (kein RGB-Picker); Kachel-Auto = kein Hintergrund. So faerben sich Zahl und Kachel nach der Menge unbestaetigter Meldungen. Grenzen leer = Farbe nach der hoechsten vorhandenen Severity. Schriftart/Groesse kommen aus dem Abschnitt Typografie."},
        {name: "Einzeln ausblenden / Verlauf (kein Feld)", beschreibung: "In der Symcon-Listenansicht blendet das ✕ je Zeile diese eine Meldung aus. Der Umschalter „Verlauf“ zeigt die bestätigten/ausgeblendeten wieder an, ausgegraut; einzeln ausgeblendete tragen dort ein ↺ zum Zurückholen (Cutoff-bestätigte holt man über ein neues „Bestätigen“ bzw. Anpassen der Variable zurück). Nichts wird gelöscht, alles bleibt im Log. Verlauf-Zustand je Gerät im Browser (localStorage lvmsghist_<Widget-ID>)."},
        {name: "Darstellung", beschreibung: "Liste (Zeilen mit Farbpunkt, Kategorie und Text) oder Kompakt: EINE große, prominente Zahl = Anzahl der vollständigen gefilterten Liste der aktiven Quelle (Anzahl Symcon ODER Anzahl Homematic, je nach eingestellter Quelle), gefärbt nach der höchsten vorhandenen Severity — ohne Kategorie-Pillen und ohne Quell-Umschalter, skaliert mit der Kachelgröße. Der Zähler ist NICHT durch „Max. Einträge“ begrenzt (im Kompaktmodus werden bis 999 Symcon-Treffer gezählt). Welche Kategorien zählen, bestimmt der Severity-Filter; bei Symcon zählen nur OFFENE (unbestätigte) Meldungen (siehe Bestätigen)."},
        {name: "Standard-Filter (Builder)", beschreibung: "Sechs Kästchen ERROR, WARNING, CUSTOM, NOTIFY, MESSAGE, SUCCESS. Nur angehakte Kategorien werden geholt/gezählt. Ohne eigene Einstellung sind ERROR, WARNING und CUSTOM aktiv. Homematic-Typen werden gemappt: UNREACH/LOWBAT/CONFIG_PENDING → WARNING/NOTIFY, FAULT_REPORTING/SABOTAGE → ERROR."},
        {name: "Pillen im Betrieb (kein Feld)", beschreibung: "Nur in der Listen-Ansicht: Ein Tipp auf eine farbige Kategorie-Pille im Kopf des Widgets schaltet diese Kategorie um. Der Zustand wird je Gerät im Browser gespeichert (localStorage, Schlüssel lvmsg_<Widget-ID>) und überlagert dort den Builder-Filter. Im Kompaktmodus sind die Pillen ausgeblendet — die Kategorien werden dann im Builder-Filter festgelegt."},
        {name: "Neuen folgen", beschreibung: "Kästchen (Vorgabe an): scrollt bei neuen Meldungen ans Ende der Liste — aber nur, wenn man bereits ganz unten steht. Wer nach oben gescrollt hat, wird nicht weggerissen."},
        {name: "Max. Einträge", beschreibung: "Wie viele Meldungen gehalten/gezählt werden, 1 bis 500 (Vorgabe 25). Der Server durchsucht das Log rückwärts und liefert die letzten Treffer der aktiven Kategorien — zeitunabhängig, aber begrenzt auf die letzten rund 3 MB der Logdatei. Im Kompaktmodus wird bis zu diesem Maximum (max. 500) gezählt."},
        {name: "Aktualisierung (Sek.)", beschreibung: "Eigener Abrufabstand dieses Widgets, 1 bis 600. Leer = globaler Wert aus den Ansicht-Einstellungen (Vorgabe 15 s). Ein 1-Sekunden-Grundtakt prüft, welches Meldungs-Widget fällig ist; auch Widgets in Laufzeilen und Popups werden versorgt."},
        {name: "Neuzeichnen nur bei Änderung (kein Feld)", beschreibung: "Die geholte Liste wird mit einer Signatur verglichen. Ist nichts Neues dabei, bleibt der Inhalt unangetastet — dadurch ruckelt der Scrollbereich nicht."},
        {name: "Zustandsfärbung (kein Feld)", beschreibung: "Punkt, Kategoriekürzel und Pillenrahmen sind je Schwere eingefärbt: ERROR rot, WARNING gelb, CUSTOM violett, NOTIFY blau, MESSAGE grau, SUCCESS grün."},
        {name: "Label", beschreibung: "Überschrift links neben den Pillen (Vorgabe „Meldungen“)."},
        {name: "Farben / Rahmen / Hintergrund / Beschriftung", beschreibung: "Text- und Hintergrundfarbe, Kachelrahmen an/aus/Ansicht-Standard, Hintergrund deckend oder transparent, Beschriftung mehrzeilig statt abschneiden."},
        {name: "Typografie", beschreibung: "Schriftart, Gewicht, Stil und Schriftgröße für das ganze Widget."},
        {name: "Interaktion", beschreibung: "Seite öffnen, Lang-Druck → Seite, Popup öffnen, Lang-Druck → Popup, Popup schließen, Skript-ID bei Klick. Ein Klick auf eine Pille wird vom Widget selbst verarbeitet und löst diese Aktionen nicht aus; ein Klick daneben schon."},
        {name: "Sichtbarkeit", beschreibung: "Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung (wahr/≠0, = , ≠, ≥, ≤ Wert), Verschieben in eine Laufzeile (nur wenn auf der Seite eine Laufzeile liegt)."},
        {name: "Animation / Ebene / Position", beschreibung: "Einblend-Animation (Fade, Scale, SlideUp), nach vorn/hinten legen, X, Y, Breite, Höhe."},
      ],
      hinweis: "Findet der Server keine passenden Zeilen (oder ist das Log nicht lesbar), steht „Keine Meldungen“ da; „Log nicht lesbar“ erscheint nur, wenn die Abfrage selbst scheitert. Sind alle Pillen aus, steht dort „Keine Kategorie aktiv“. Der Pillen-Zustand aus dem Betrieb wird pro Browser gespeichert und überstimmt den im Builder gesetzten Standard-Filter; wer den Standard testen will, muss den Browser-Speicher leeren oder alle Pillen wieder anschalten. Das allgemeine Feld „Variable“ oben hat für dieses Widget keine Wirkung.",
      groesse: [520,270],
      demo: {"label": "Meldungen", "max": 20, "sev": {"ERROR": 1, "WARNING": 1, "CUSTOM": 1, "NOTIFY": 1, "MESSAGE": 1, "SUCCESS": 1}, "refreshSec": 15}
    },
