      funktionen: [
        {name: "Variable", beschreibung: "Erste Metrik (varId), links in der Wertzeile."},
        {name: "Metrik 2", beschreibung: "Zweite Variable (varId2). Ist sie leer, fehlt der zweite Wert komplett — samt zugehörigem Einheitenfeld."},
        {name: "Metrik 3", beschreibung: "Dritte Variable (varId3), analog zur zweiten."},
        {name: "Einheit", beschreibung: "Freitext hinter dem ersten Wert, klein und gedämpft (z. B. °C). Steht hier etwas, wird bei allen drei Werten die Einheit aus dem Variablenprofil vom Zahlenwert abgeschnitten, damit sie nicht doppelt erscheint."},
        {name: "Einheit 2 / Einheit 3", beschreibung: "Dasselbe für die zweite und dritte Metrik. Die Felder erscheinen im Editor erst, sobald die jeweilige Variable eingetragen ist."},
        {name: "Format", beschreibung: "Darstellungsform des Werts (Auto, kW, kWh, W, 0/1 Dezimale, Prozent, Uhrzeit, Datum, Relativzeit), gilt für alle drei Metriken."},
        {name: "Nachkommastellen", beschreibung: "Feste Stellenzahl 0 bis 6 aus dem Rohwert gerechnet; ohne Angabe zeigt das Widget den formatierten Wert von Symcon."},
        {name: "Icon (Fallback)", beschreibung: "Symbol links oben; ohne Auswahl wird das Haus-Icon verwendet."},
        {name: "Icon-Farbe", beschreibung: "Skin-Farbfeld (Standard, Akzent, OK, Warnung, Kritisch, Info, Neutral). Erscheint erst, wenn ein Icon gesetzt ist, und färbt es themetreu statt mit fester Hexfarbe."},
        {name: "Assoziationen", beschreibung: "Erscheint bei Variablen mit Profil-Zuordnungen: „Icons & Farben nutzen“ übernimmt Symbol und Farbe je Zustand der ersten Variablen; jeder Zustand lässt sich mit eigenem Icon und eigener Skin-Farbe belegen."},
        {name: "Label", beschreibung: "Raumname rechts neben dem Icon. Ein \\n im Text erzwingt einen Zeilenumbruch."},
        {name: "Live-Aktualisierung (kein Feld)", beschreibung: "Jede der drei Variablen aktualisiert gezielt ihren eigenen Wert; die übrigen bleiben unangetastet."},
        {name: "Farben / Rahmen / Hintergrund / Beschriftung", beschreibung: "Text- und Hintergrundfarbe, Kachelrahmen, transparenter Hintergrund, mehrzeilige Beschriftung."},
        {name: "Typografie", beschreibung: "Schriftart, Gewicht, Stil, Schriftgröße; die Zahlen laufen in der Monospace-Schrift."},
        {name: "Interaktion", beschreibung: "Seite öffnen, Lang-Druck → Seite, Popup öffnen, Lang-Druck → Popup, Popup schließen, Skript-ID bei Klick. Typisch: Klick öffnet die Raumseite, Lang-Druck ein Detail-Popup."},
        {name: "Sichtbarkeit", beschreibung: "Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Verschieben in eine Laufzeile."},
        {name: "Animation / Ebene / Position", beschreibung: "Einblend-Animation, Reihenfolge, X, Y, Breite, Höhe."},
      ],
      hinweis: "Die Kachel ist reine Anzeige — sie schaltet nichts. Die drei Werte stehen in einer Zeile nebeneinander; bei schmaler Kachel oder langen Zahlen wird es schnell eng, dann lieber breiter ziehen oder auf zwei Metriken beschränken. Format und Nachkommastellen gelten gemeinsam für alle drei Werte, getrennte Einstellungen gibt es nicht. Stolperfalle: Das Abschneiden der Profil-Einheit hängt allein am ersten Feld „Einheit“ — bleibt es leer und sind nur Einheit 2/3 gefüllt, steht die Einheit dort doppelt.",
