      funktionen: [
        {name: "Variable", beschreibung: "Ziel-Variable. Ihr Rohwert wird beim Aufbau in das Feld geschrieben; die Eingabe wird beim Verlassen des Feldes bzw. mit Enter (change-Ereignis) per setVar dorthin zurueckgeschrieben."},
        {name: "Label", beschreibung: "Wird NICHT als Beschriftung gezeichnet, sondern als Platzhaltertext im leeren Feld angezeigt. Ein \\n wird hier nicht in einen Zeilenumbruch umgesetzt (der Platzhalter wird ohne Umbruch-Ersetzung gesetzt)."},
        {name: "Mehrzeilig", beschreibung: "Schaltet von <input> auf <textarea> um (Textfeld statt Zeile, Groessenaenderung durch den Benutzer gesperrt, Schrift 13px statt 14px)."},
        {name: "Passwort", beschreibung: "Eingabe verbergen: rendert type=password statt type=text. Nur im einzeiligen Modus wirksam, da das mehrzeilige Feld immer Klartext zeigt."},
        {name: "Live-Aktualisierung", beschreibung: "Aendert sich die Variable von aussen, wird der Feldinhalt nachgezogen - aber nur, wenn das Feld gerade NICHT den Fokus hat. Eine laufende Eingabe wird also nicht ueberschrieben."},
        {name: "Schreiben nur im Betrieb", beschreibung: "Der Eingabe-Handler laeuft nur ausserhalb des Bearbeiten-Modus. Im Editor ist das Feld sichtbar, schreibt aber nicht."},
        {name: "Farben / Rahmen / Hintergrund", beschreibung: "Gemeinsame Eigenschaften. Sie greifen hier kaum: Das Feld liegt deckend ueber der ganzen Kachel und zeichnet einen eigenen Rahmen in --line, --surface-2 als Fuellung und eine feste Textfarbe --text - Textfarbe, Hintergrundfarbe und Rahmen-Schalter des Widgets bleiben dadurch unsichtbar. Nur \"Hintergrund transparent\" wirkt: es nimmt dem Feld Fuellung und Rahmen."},
        {name: "Typografie", beschreibung: "Schriftart, Gewicht, Stil und Schriftgroesse. Ohne eigene Wahl nutzt das Feld die Schriftart der Ansicht (--fu); eine gesetzte Typografie wird per !important auf das Eingabefeld durchgereicht und ueberschreibt auch die 13/14px."},
        {name: "Beschriftung mehrzeilig", beschreibung: "Gemeinsame Option (lblWrap). Ohne sichtbare Wirkung, da dieses Widget keine Beschriftung zeichnet."},
        {name: "Interaktion", beschreibung: "Gemeinsame Sektion: Seite oeffnen, Lang-Druck auf Seite/Popup, Popup oeffnen, Popup schliessen, Skript-ID bei Klick. Achtung - diese Aktionen feuern auch beim Antippen des Eingabefeldes."},
        {name: "Sichtbarkeit", beschreibung: "Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung (wahr/=/!=/>=/<=), Verschieben in eine Laufzeile."},
        {name: "Animation / Ebene / Geometrie", beschreibung: "Einblend-Animation (Fade, Scale, SlideUp), nach vorn/hinten legen, X/Y/Breite/Hoehe."},
      ],
      hinweis: "Schreibt in die gebundene Variable, sobald das Feld verlassen wird - in der Doku-Vorschau haengt es an der echten String-Variablen #26237 (Steuerung\\System Dashboard\\erzeugen\\Texttafel, Profil ~TextBox); getippter Text landet also wirklich dort. Der Server wandelt den Text in den Variablentyp um und schreibt per RequestAction (falls Aktion hinterlegt), sonst per SetValue.",
      groesse: [240,90],
      demo: {"varId": 26237, "label": "Text eingeben", "multi": false}
