      funktionen: [
        {name: "Variable", beschreibung: "Quelle der Restzeit. Werte groesser 1.000.000.000 werden als Unix-Zeitstempel verstanden und die Differenz zu jetzt gebildet; kleinere Werte gelten direkt als Restsekunden. Negative Ergebnisse werden auf 0 gekappt."},
        {name: "Max", beschreibung: "Gesamtdauer in Sekunden fuer den Balken (Vorgabe 3600). Die Balkenbreite ist Restzeit/Max, auf 0 bis 100 % begrenzt."},
        {name: "Min", beschreibung: "Wird zwar angeboten (gemeinsame Min/Max-Zeile), vom Timer aber nicht ausgewertet."},
        {name: "Label", beschreibung: "Bezeichnung links in der Kopfzeile; \\n erzwingt einen Zeilenumbruch."},
        {name: "Sekuendliche Aktualisierung", beschreibung: "Der Timer haengt an der globalen Sekundenschleife (wie die Uhr) und zaehlt selbstaendig herunter - auch ohne neue Variablenwerte. Das gilt auch fuer Timer innerhalb von Komponenten und Laufzeilen."},
        {name: "Farben / Rahmen / Hintergrund / Typografie", beschreibung: "Gemeinsame Gestaltung: Vorder- und Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schriftart/Gewicht/Stil/Groesse, mehrzeilige Beschriftung. Restzeit und Balken werden in der Akzentfarbe gezeichnet, die Zeit in Mono-Schrift."},
        {name: "Interaktion", beschreibung: "Seite oeffnen, Popup oeffnen, Lang-Druck auf Seite/Popup, Popup schliessen, Skript-ID bei Klick."},
        {name: "Sichtbarkeit / Animation / Ebene / Geometrie", beschreibung: "Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/B/H."},
      ],
      hinweis: "Rein anzeigend - der Timer startet und stoppt nichts, er stellt nur eine Variable dar. Es gibt weder eine Formatwahl noch Nachkommastellen; die Anzeige ist fest mm:ss bzw. h:mm:ss. Liegt der Zeitstempel in der Vergangenheit oder ist die Restzeit 0, steht dauerhaft 00:00 und der Balken ist leer. Ohne passend gesetztes Max ist der Balken sofort voll. Die Vorschau haengt an #16467 (Location\\Sonnenuntergang, Profil ~UnixTimestamp).",
      groesse: [230,90],
      demo: {"varId": 16467, "max": 86400, "label": "Bis Sonnenuntergang"}
